  const setFloatingText=(v:string)=>{if(!selection)return;const key=selection.key;if(navObject)patchNav(key,{text:v});else if(selection.kind==='slot')edit(c=>changeText(c,key as TextSlot,v));else if(selection.kind==='customer')edit(c=>({...c,customerText:{...c.customerText,[key]:v}}));else if(selection.kind==='banner')patchBanner({[key]:v});else if(activeObject)patchObject(selection.block,key,{text:v});};
  const setFloatingStyle=(patch:Partial<TextPresentation>)=>{if(!selection)return;const key=selection.key;if(navObject)patchNav(key,{presentation:{...navObject.presentation,...patch}});else if(selection.kind==='slot')edit(c=>({...c,textPresentations:{...c.textPresentations,[c.theme]:{...c.textPresentations[c.theme],[key]:{...c.textPresentations[c.theme][key as TextSlot],...patch}}}}));else if(selection.kind==='customer')edit(c=>({...c,customerTextStyles:{...c.customerTextStyles,[key]:{...(c.customerTextStyles[key]||defaultPresentation),...patch}}}));else if(selection.kind==='banner')patchBanner({typography:{...banner.typography,[key]:{...floatingStyle,...patch}},...(patch.color?{textColors:{...banner.textColors,[key]:patch.color}}:{})});else if(activeObject)patchObject(selection.block,key,{presentation:{...activeObject.presentation,...patch}});};

  const canLink=!!selection&&(!!navObject||activeObject?.kind==='text'||activeObject?.kind==='button'||isLinkableText(selection.key));
  const currentLink=navObject?.link??activeObject?.link??(selection?draft.textLinks[selection.key]||(selection.key==='navButton.0'?'/all-products':selection.key==='navButton.1'?'/#custom-builder':selection.key==='navButton.3'?'/#ribbon-story':''):'');
  const setLink=(value:string)=>{if(!selection)return;const link=safeTextLink(value);if(navObject)patchNav(navObject.id,{link});else if(activeObject)patchObject(selection.block,activeObject.id,{link,linkEnabled:!!link});else if(isLinkableText(selection.key))edit(c=>({...c,textLinks:{...c.textLinks,[selection.key]:link}}));};
