  if(!data)return <div className="flex min-h-screen flex-col items-center justify-center gap-4 bg-slate-50 p-6 text-center"><h1 className="text-xl font-semibold">Jame Bouquets Studio</h1><p className="text-sm">{error||'Loading secure workspace…'}</p><div className="flex gap-2"><button className={btn} onClick={onExit}>Back</button>{error&&<button className={btn} onClick={()=>void load()}>Retry</button>}</div></div>;
