        {inspector==='layout'&&<><Group title="Homepage layers">{draft.sections.order.map((id,i)=><div key={id} draggable onDragStart={()=>{drag.current=id;}} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();move(drag.current,id);drag.current='';}} className="flex items-center gap-1 rounded border border-slate-200 p-2"><input aria-label={'Show '+id} type="checkbox" checked={draft.sections.visible[id]} onChange={e=>edit(c=>({...c,sections:{...c.sections,visible:{...c.sections.visible,[id]:e.target.checked}}}))}/><button className="min-w-0 flex-1 truncate text-left text-xs" onClick={()=>{if(id.startsWith('block-')){setBlockId(id);setInspector('block');}else if(id==='collections')choose('collections');else if(id==='shop')choose('cards');else {setSlot((id==='reviews'?'hero':id)+'.heading' as TextSlot);choose('text');}}}>{sectionLabels[id]||draft.blocks.find(b=>b.id===id)?.title||id}</button><button className={btn} disabled={i===0} onClick={()=>move(id,draft.sections.order[i-1])} aria-label="Move up"><ArrowUp size={12}/></button><button className={btn} disabled={i===draft.sections.order.length-1} onClick={()=>move(id,draft.sections.order[i+1])} aria-label="Move down"><ArrowDown size={12}/></button></div>)}</Group><Group title="Add section">{BLOCK_KINDS.map(b=><button key={b.id} className={btn+' w-full justify-start'} onClick={()=>addBlock(b.id)}><Plus size={13}/>{b.label}</button>)}</Group></>}
